"style": {
"look": "Stop-motion miniature aesthetic with physically plausible 3D shading, not a painting or 2D illustration",
"handcrafted": "Visible stitches, seams, and fiber textures; slight surface imperfections and edge wear",
"palette": "Cool blue-teal vs warm tungsten contrast; desaturated midtones; moody theatrical shadows"
},
"materials": {
"skin": "Painted silicone/latex with matte finish; faint faceplate seam suggestion; tiny freckles or pores as paint specks",
"hair": "Converted to yarn or felted fibers that match the input color and style (strand clumping, slight fuzz/pilling)",
"clothing": "Same design/colors as input image, reinterpreted as stitched cotton/denim/wool with visible hems and topstitching",
"accessories": "Replicate all input accessories in miniature craft materials (painted wood, metal brads, thread, felt)"
},
"character": {
"preserve_identity": "Maintain the same face geometry, skin tone, hairstyle, clothing and accessories from the input",
"exaggeration": {
"head_scale": "Slightly oversized (≈1.15x the natural proportion)",
"limbs": "Elongated and slender; delicate hands",
"features": "Small triangular nose, subtle lips; lightly defined brows (embroidered or painted)"
},
"eyes": {
"type": "Sewn-on button eyes",
"spec": "Matte black (or dark glossy resin) 2-hole or 4-hole buttons, stitched with thread in an X or || pattern; shallow indentations from thread tension; minimal specular highlight",
"note": "No visible iris or sclera; ensure the buttons match face scale and sit correctly on the sockets"
}
},
"camera": {
"framing": "Portrait, waist-up or tighter; character centered",
"lens": "Macro-ish 50–80mm equivalent with shallow depth of field; slight vignette",
"scale_cues": "Overscaled wood grain, fabric fibers, and hand-painted textures to reinforce miniature scale",
"lighting": "Practical tungsten key with soft rim light; cool moonlight fill from window; crisp puppet shadows"
},
"background": {
"environment": "Crooked, whimsical interior with hand-painted wallpaper, tilted frames, stitched or patched props; optional rainy window and thread/spool motifs",
"focus": "Softened/defocused background to keep attention on the character",
"depth": "Layered set pieces to enhance parallax and 3D feel"
},
"vibe": {
"tone": "Dark yet whimsical; playful gothic charm with a faintly eerie, surreal mood",
"emotion": "Curious, brave, slightly uneasy"
},
"constraints": {
"preserve_from_input": ["face", "hairstyle and color", "clothing design and colors", "all accessories"],
"must_have": ["button eyes as specified", "stop-motion 3D miniature look"],
"avoid": ["2D illustration, painterly brushstrokes, anime/comic style, photoreal human eyes, airbrushed plastic look"]
},
"output": {
"size": "1536x2048",
"aspect_ratio": "3:4",
"orientation": "portrait",
"n": 1
}
}

